// ❌ 공유 객체 — 한 테스트가 고치면 다음 테스트가 오염된다
const 사용자 = { id: 1, 이름: '카르모', 잔액: 1000 };
test('A', () => { 사용자.잔액 -= 500; ... });  // 사용자를 오염
test('B', () => { expect(사용자.잔액).toBe(1000); });  // 500 이라 빨강!

// ✅ 팩토리 함수 — 매번 새로 만들고, 필요한 것만 덮어쓴다
function 새사용자(덮어쓰기 = {}) {
  return { id: 1, 이름: '카르모', 잔액: 1000, ...덮어쓰기 };
}
test('A', () => { const u = 새사용자({ 잔액: 500 }); ... });  // 자기 것
test('B', () => { const u = 새사용자(); expect(u.잔액).toBe(1000); });  // 독립

let 임시경로;
beforeEach(() => {
  임시경로 = fs.mkdtempSync(path.join(os.tmpdir(), 't-'));  // 고유 임시 디렉터리
});
afterEach(() => {
  fs.rmSync(임시경로, { recursive: true, force: true });   // 반드시 정리
});

// 더 나은 방법: 트랜잭션 롤백 (DB 가 항상 깨끗)
beforeEach(async () => { await db.begin(); });
afterEach(async () => { await db.rollback(); });  // 변경을 통째로 되돌림

// 정리는 실패해도 반드시 실행 (afterEach 는 테스트 실패해도 돎)
